<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">cuMemGetAllocationGranularity</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">(</span><span style="--shiki-light:#A626A4;--shiki-dark:#56B6C2;">&amp;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">granularity, </span><span style="--shiki-light:#A626A4;--shiki-dark:#56B6C2;">&amp;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">prop, CU_MEM_ALLOC_GRANULARITY_MINIMUM);</span></span>
